with a as(select * from public.authors where open_library_id=any(array['OL51383A','OL450608A']::text[])),w as(select * from public.works where open_library_id=any(array['OL34828070W','OL2952400W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789492241078','9789022991411']::text[]) or open_library_edition_id=any(array['OL47182046M','OL41839615M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987125001 and 987125999),'editions',(select count(*) from public.editions where id between 987225001 and 987225999),'authors',(select count(*) from public.authors where id between 987325001 and 987325999))) as preflight;
